<body>
    <!-- Mobile Menu Toggle -->
    <button class="menu-toggle" onclick="toggleSidebar()">☰</button>
    <div class="mobile-overlay" onclick="toggleSidebar()"></div>

    <!-- Progress Bar -->
    <div class="progress-bar">
        <div class="progress-fill" id="progressFill"></div>
    </div>

    <!-- SIDEBAR -->
    <div id="sidebar">
        <div class="sidebar-header">
            <a href="/" class="nav-home">
                <span>←</span>
                <span>Library</span>
            </a>
            <div class="book-title-sidebar">{{ book.metadata.title }}</div>
        </div>

        <div class="toc-container">
            <div class="toc-section-label">Contents</div>

            {% macro render_toc(items) %}
                <ul class="toc-list">
                {% for item in items %}
                    <li class="toc-item">
                        {% set is_active = current_chapter.href == item.file_href %}
                        <a href="#" onclick="findAndGo('{{ item.file_href }}'); return false;"
                           class="toc-link {% if is_active %}active{% endif %}">
                            {{ item.title }}
                        </a>
                        {% if item.children %}
                            {{ render_toc(item.children) }}
                        {% endif %}
                    </li>
                {% endfor %}
                </ul>
            {% endmacro %}

            {{ render_toc(book.toc) }}
        </div>
    </div>

    <!-- MAIN CONTENT -->
    <div id="main">
        <div class="content-container">
            <div class="book-content">
                {{ current_chapter.content | safe }}
            </div>

            <div class="chapter-nav">
                {% if prev_idx is not none %}
                    <a href="/read/{{ book_id }}/{{ prev_idx }}" class="nav-btn">
                        <span>←</span>
                        <span>Previous</span>
                    </a>
                {% else %}
                    <span class="nav-btn disabled">
                        <span>←</span>
                        <span>Previous</span>
                    </span>
                {% endif %}

                <span class="chapter-progress">
                    Chapter {{ chapter_index + 1 }} of {{ book.spine|length }}
                </span>

                {% if next_idx is not none %}
                    <a href="/read/{{ book_id }}/{{ next_idx }}" class="nav-btn">
                        <span>Next</span>
                        <span>→</span>
                    </a>
                {% else %}
                    <span class="nav-btn disabled">
                        <span>Next</span>
                        <span>→</span>
                    </span>
                {% endif %}
            </div>
        </div>
    </div>

    <script>
        // Spine mapping for TOC navigation
        const spineMap = {
            {% for ch in book.spine %}
            "{{ ch.href }}": {{ ch.order }},
            {% endfor %}
        };

        function findAndGo(filename) {
            const cleanFile = filename.split('#')[0];
            const idx = spineMap[cleanFile];

            if (idx !== undefined) {
                window.location.href = "/read/{{ book_id }}/" + idx;
            }
        }

        // Mobile sidebar toggle
        function toggleSidebar() {
            const sidebar = document.getElementById('sidebar');
            const overlay = document.querySelector('.mobile-overlay');
            sidebar.classList.toggle('open');
            overlay.classList.toggle('active');
        }

        // Reading progress indicator
        const mainElement = document.getElementById('main');
        const progressFill = document.getElementById('progressFill');

        mainElement.addEventListener('scroll', () => {
            const scrollTop = mainElement.scrollTop;
            const scrollHeight = mainElement.scrollHeight - mainElement.clientHeight;
            const progress = (scrollTop / scrollHeight) * 100;
            progressFill.style.width = progress + '%';
        });

        // Keyboard navigation
        document.addEventListener('keydown', (e) => {
            {% if prev_idx is not none %}
            if (e.key === 'ArrowLeft') {
                window.location.href = "/read/{{ book_id }}/{{ prev_idx }}";
            }
            {% endif %}
            {% if next_idx is not none %}
            if (e.key === 'ArrowRight') {
                window.location.href = "/read/{{ book_id }}/{{ next_idx }}";
            }
            {% endif %}
        });
    </script>
</body>
